def calculate_sequence(a, n, max_k):
    a_k_minus_1 = a
    results = {0: a}
    for k in range(1, max_k + 1):
        # a_k = a_{k-1} / k + k^{n-1}
        try:
            # Check for required divisibility before division
            if k > 1 and a_k_minus_1 % k != 0:
                return None, f"Failure at k={k}: {a_k_minus_1} is not divisible by {k}"

            a_k = (a_k_minus_1 / k) + (k**(n-1))

            # Ensure a_k is an integer
            if a_k != int(a_k):
                 return None, f"Failure at k={k}: a_k is not an integer ({a_k})"

            results[k] = int(a_k)
            a_k_minus_1 = int(a_k)
        except ZeroDivisionError:
            return None, "Division by zero error."

    return results, "Success"

# Task verification: n=4, check up to k=4. Test a=13.
n_test = 4
